describe('Async PDF Generation Download', () => {
  beforeEach(() => {
    cy.visit('/pdf-generator');
  });

  it('should generate and download PDF when async process completes', () => {
    // Intercept the PDF generation API call
    cy.intercept('POST', '/api/generate-pdf').as('generatePdf');

    // Click the generate PDF button
    cy.get('[data-testid="generate-pdf-btn"]').click();

    // Verify loading state appears
    cy.get('[data-testid="loading-spinner"]').should('be.visible');
    cy.get('[data-testid="loading-text"]').should('contain', 'Generating PDF');

    // Wait for the API call to complete
    cy.wait('@generatePdf');

    // Verify loading state is removed
    cy.get('[data-testid="loading-spinner"]').should('not.exist');

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'PDF generated successfully');

    // Verify download link appears
    cy.get('[data-testid="download-pdf-btn"]').should('be.visible');

    // Click the download button to trigger download
    cy.get('[data-testid="download-pdf-btn"]').click();

    // Verify download confirmation or file name appears
    cy.get('[data-testid="download-confirmation"]').should('be.visible');
    cy.get('[data-testid="download-confirmation"]').should('contain', 'PDF download started');

    // Verify download link is disabled after click
    cy.get('[data-testid="download-pdf-btn"]').should('be.disabled');
  });

  it('should handle PDF generation failure and display error message', () => {
    // Intercept the PDF generation API call and mock a failure response
    cy.intercept('POST', '/api/generate-pdf', {
      statusCode: 500,
      body: { error: 'Internal server error during PDF generation' }
    }).as('generatePdfFailure');

    // Click the generate PDF button
    cy.get('[data-testid="generate-pdf-btn"]').click();

    // Verify loading state appears
    cy.get('[data-testid="loading-spinner"]').should('be.visible');

    // Wait for the failed API call
    cy.wait('@generatePdfFailure');

    // Verify loading state is removed
    cy.get('[data-testid="loading-spinner"]').should('not.exist');

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Failed to generate PDF');

    // Verify error details are displayed
    cy.get('[data-testid="error-details"]').should('be.visible');
    cy.get('[data-testid="error-details"]').should('contain', 'Internal server error');

    // Verify download button does not appear
    cy.get('[data-testid="download-pdf-btn"]').should('not.exist');

    // Verify retry button is available
    cy.get('[data-testid="retry-btn"]').should('be.visible');
    cy.get('[data-testid="retry-btn"]').should('not.be.disabled');
  });
});
